badgeCss:
.${BADGE_CLASS} {
  position: absolute;
  right: 1px;
  bottom: 1px;
  z-index: 9;
  max-width: calc(100% - 2px);
  max-height: 24%;
  padding: 1px 3px;
  border-radius: 3px;
  box-sizing: border-box;
  display: flex;
  flex-direction: row;
  align-items: baseline;
  justify-content: flex-end;
  gap: 2px;
  white-space: nowrap;
  background: rgba(0, 0, 0, 0.35);
  color: #ffffff;
  text-shadow: 0 1px 1px rgba(0, 0, 0, 0.55);
  pointer-events: none;
  user-select: none;
}
.${BADGE_CLASS}__chance {
  font-size: 9px;
  font-weight: 700;
  line-height: 1;
  flex: 0 0 auto;
}
.${BADGE_CLASS}__eta {
  font-size: 8px;
  font-weight: 600;
  line-height: 1;
  opacity: 0.95;
  flex: 0 0 auto;
}
